//! 🪪️ Fixed lifecycle projections receive only canonical decimal generations and the original bounded record fields.
use super::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_value::native_decoding::{NativeReceive,owned::tree::{NativeValueSource,NativeScalarValue,NativeScalarReceiver}};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native lifecycle receipt requires its canonical complete original fields")}
fn fields<const N:usize>(input:&dyn NativeValueSource,names:[&str;N])->Result<[Option<usize>;N],ValueError>{let count=input.record_len()?;if count>N{return Err(invalid())}let mut positions=[None;N];for index in 0..count{let name=input.record_name(index)?;if name.len()>24{return Err(invalid())}let field=names.iter().position(|expected|*expected==name).ok_or_else(invalid)?;if positions[field].replace(index).is_some(){return Err(invalid())}}Ok(positions)}
fn field(input:&dyn NativeValueSource,index:Option<usize>)->Result<&dyn NativeValueSource,ValueError>{input.record_child(index.ok_or_else(invalid)?)}
fn decimal(input:&dyn NativeValueSource)->Result<u64,ValueError>{let text=input.text()?;if text.is_empty()||text.len()>20||text.as_bytes()[0]==b'0'||!text.bytes().all(|b|b.is_ascii_digit()){return Err(invalid())}text.parse().map_err(|_|invalid())}
fn unsigned(input:&dyn NativeValueSource)->Result<u64,ValueError>{<u64 as NativeScalarValue<dyn NativeValueSource>>::read(input)}
fn request(input:&dyn NativeValueSource)->Result<u64,ValueError>{let value=unsigned(input)?;if !valid_request(value){return Err(invalid())}Ok(value)}
fn lifetime(input:&dyn NativeValueSource)->Result<ActorInstanceLifetime,ValueError>{let p=fields(input,["activationGeneration","instanceId","guestLifetime"])?;Ok(ActorInstanceLifetime{activation_generation:decimal(field(input,p[0])?)?,instance_id:<u32 as NativeScalarValue<dyn NativeValueSource>>::read(field(input,p[1])?)?,guest_lifetime:decimal(field(input,p[2])?)?})}
macro_rules! scalar{($ty:ty,$copy:expr,$read:expr)=>{impl<I:NativeValueSource+?Sized> NativeScalarValue<I> for $ty{fn read(input:&I)->Result<Self,ValueError>{($read)(input.as_source())}fn read_copy_bytes(_:&I)->Result<usize,ValueError>{Ok($copy)}}impl<I:NativeValueSource+?Sized> NativeReceive<I> for $ty{type Receiver=NativeScalarReceiver<I,Self>;fn receiver()->Self::Receiver{Self::Receiver::new()}}};}
scalar!(ActorInstanceLifetime,512,lifetime);
scalar!(ActorInstanceOpenRequest,512,|input|{let p=fields(input,["activationGeneration","instanceId","requestSequence"])?;Ok(ActorInstanceOpenRequest{activation_generation:decimal(field(input,p[0])?)?,instance_id:<u32 as NativeScalarValue<dyn NativeValueSource>>::read(field(input,p[1])?)?,request_sequence:request(field(input,p[2])?)?})});
scalar!(ActorInstanceCloseRequest,768,|input|{let p=fields(input,["lifetime","requestSequence"])?;Ok(ActorInstanceCloseRequest{lifetime:lifetime(field(input,p[0])?)?,request_sequence:request(field(input,p[1])?)?})});
scalar!(ActorUiPatchReceipt,768,|input|{let p=fields(input,["lifetime","patchSequence"])?;Ok(ActorUiPatchReceipt{lifetime:lifetime(field(input,p[0])?)?,patch_sequence:decimal(field(input,p[1])?)?})});
fn lifecycle(input:&dyn NativeValueSource)->Result<ActorInstanceLifecycleReceipt,ValueError>{let p=fields(input,["kind","lifetime","requestSequence","closeGeneration"])?;let kind=field(input,p[0])?.text()?;if kind.len()>8{return Err(invalid())}let lifetime=lifetime(field(input,p[1])?)?;let request_sequence=request(field(input,p[2])?)?;Ok(match kind.as_str(){"captured" if p[3].is_none()=>ActorInstanceLifecycleReceipt::Captured{lifetime,request_sequence},"accepted"=>ActorInstanceLifecycleReceipt::Accepted{lifetime,request_sequence,close_generation:decimal(field(input,p[3])?)?},"retired"=>ActorInstanceLifecycleReceipt::Retired{lifetime,request_sequence,close_generation:decimal(field(input,p[3])?)?},_=>return Err(invalid())})}
scalar!(ActorInstanceLifecycleReceipt,1024,lifecycle);
scalar!(ActorInstanceLifecycleAck,1280,|input|{let p=fields(input,["receipt"])?;Ok(ActorInstanceLifecycleAck{receipt:lifecycle(field(input,p[0])?)?})});
